/* 효과음 (사용자가 준 소리)
   - playFart(): 게임에서 탈락했을 때 (뿡!)
   - playJoinSound(): 방에 친구가 들어왔을 때 (띠링)
   - 메뉴 버튼(게임 고르기, 시작, 뒤로가기 등)을 누를 때 딸깍 */
var FART_SOUND_SRC = "data:audio/mpeg;base64,";
var JOIN_SOUND_SRC = "data:audio/mpeg;base64,";
var SFX_CACHE = {};
function sfxPlay(src, vol) {
  try {
    var base = SFX_CACHE[src] || (SFX_CACHE[src] = new Audio(src));
    var a = base.cloneNode();
    a.volume = vol || 0.9;
    var p = a.play(); if (p && p.catch) p.catch(function () {});
  } catch (e) {}
}
function playFart() { sfxPlay(FART_SOUND_SRC, 0.9); }
function playJoinSound() { sfxPlay(JOIN_SOUND_SRC, 0.7); }
var CLICK_SOUND_SRC = "data:audio/mpeg;base64,";
function playClickSound() { sfxPlay(CLICK_SOUND_SRC, 0.6); }
/* 딸깍 소리는 메뉴용 버튼에만 (게임 안에서 빠르게 연타하는 버튼·그림판에는 안 나요) */
var CLICK_SOUND_SEL = '.game-card, .mode-btn, .mode-back, .back-btn, .btn, .rules-arrow, .rules-dot, .rules-close, .rules-exit, .group-toggle-btn, .group-tab, .group-panel-close, .yg-cat, .cm-choice, .rl-tool, .pj-tab-chat, [data-t], .char-opt, .sd-diff-btn, .diff-btn, .level-btn';
var CLICK_SOUND_SKIP = '.yg-quick, #cm-send, .wd-key, .db-sym, .ld-pad, .bm-touch-row, #rl-canvas, #cm-canvas';
document.addEventListener('pointerdown', function (e) {
  if (e.button !== undefined && e.button !== 0) return;
  var t = e.target && e.target.closest ? e.target : null;
  if (!t || t.closest(CLICK_SOUND_SKIP)) return;
  var b = t.closest(CLICK_SOUND_SEL);
  if (!b || b.disabled) return;
  playClickSound();
}, true);
/* 폭탄 돌리기: 내가 폭탄을 들고 단어를 입력하는 동안 째깍째깍 (계속 반복) */
var TIMER_SOUND_SRC = "data:audio/mpeg;base64,";
var TIMER_AUDIO = null;
function timerSoundOn() {
  try {
    if (!TIMER_AUDIO) { TIMER_AUDIO = new Audio(TIMER_SOUND_SRC); TIMER_AUDIO.loop = true; TIMER_AUDIO.volume = 0.6; }
    if (TIMER_AUDIO.paused) { TIMER_AUDIO.currentTime = 0; var p = TIMER_AUDIO.play(); if (p && p.catch) p.catch(function () {}); }
  } catch (e) {}
}
function timerSoundOff() { try { if (TIMER_AUDIO && !TIMER_AUDIO.paused) TIMER_AUDIO.pause(); } catch (e) {} }
/* "인정 못 해!" / "땡!"으로 탈락(단어 취소)될 때 */
var REJECT_SOUND_SRC = "data:audio/mpeg;base64,";
var REJECT_SEEN = {};
/* 같은 일(key)로는 한 번만, 그리고 화면을 처음 열었을 때 이미 있던 건 소리 없이 */
function playRejectOnce(game, key) {
  if (!key) return;
  if (REJECT_SEEN[game] === undefined) { REJECT_SEEN[game] = key; return; }
  if (REJECT_SEEN[game] === key) return;
  REJECT_SEEN[game] = key;
  if (key.indexOf('none') === 0) return;
  sfxPlay(REJECT_SOUND_SRC, 0.9);
}
/* 게임이 끝나면 이긴 사람을 노래와 함께 크게 띄워요 (게임 한 판에 한 번만) */
var WIN_SOUND_SRC = "data:audio/mpeg;base64,";
var WIN_SHOWN = {}, WIN_AUDIO = null, WIN_TIMER = null;
function celebrateWin(key, winners, sub) {
  if (!key || WIN_SHOWN[key]) return;
  WIN_SHOWN[key] = 1;
  winners = (winners || []).filter(Boolean);
  if (!winners.length) return;
  var ov = document.getElementById('win-pop');
  if (!ov) {
    ov = document.createElement('div');
    ov.id = 'win-pop'; ov.className = 'win-pop';
    ov.innerHTML = '<div class="win-card"><div class="win-confetti"></div><div class="win-crown">🏆</div><div class="win-label">우승</div><div class="win-names"></div><div class="win-sub"></div><button class="btn btn-primary win-ok">좋아요!</button></div>';
    document.body.appendChild(ov);
    ov.addEventListener('click', function (e) { if (e.target === ov || e.target.classList.contains('win-ok')) closeWinPop(); });
  }
  ov.querySelector('.win-names').textContent = winners.join(', ');
  ov.querySelector('.win-sub').textContent = sub || '';
  var cf = ov.querySelector('.win-confetti'), html = '', cols = ['#ffd54f', '#ff7a9a', '#7cc7ff', '#9be08f', '#c79bff', '#ffb74d'];
  for (var i = 0; i < 40; i++) html += '<i style="left:' + (Math.random() * 100) + '%;background:' + cols[i % cols.length] + ';animation-delay:' + (Math.random() * 1.2).toFixed(2) + 's;animation-duration:' + (1.8 + Math.random() * 1.6).toFixed(2) + 's"></i>';
  cf.innerHTML = html;
  ov.style.display = 'flex';
  try {
    if (WIN_AUDIO) WIN_AUDIO.pause();
    WIN_AUDIO = new Audio(WIN_SOUND_SRC); WIN_AUDIO.volume = 0.8;
    var p = WIN_AUDIO.play(); if (p && p.catch) p.catch(function () {});
  } catch (e) {}
  clearTimeout(WIN_TIMER);
  WIN_TIMER = setTimeout(closeWinPop, 12000);
}
function closeWinPop() {
  clearTimeout(WIN_TIMER);
  var ov = document.getElementById('win-pop');
  if (ov) ov.style.display = 'none';
  if (WIN_AUDIO) {
    var a = WIN_AUDIO, v = a.volume;
    var fade = setInterval(function () { v -= 0.08; if (v <= 0) { clearInterval(fade); a.pause(); } else a.volume = v; }, 60);
  }
}
